import pytest
from candidate import triangle_area


class TestTriangleArea(unittest.TestCase):
    def test_right_triangle_3_4_5(self):
        self.assertEqual(triangle_area(3, 4, 5), 6.0)

    def test_equilateral_triangle_side_5(self):
        self.assertAlmostEqual(triangle_area(5, 5, 5), 10.83, places=2)

    def test_equilateral_triangle_side_1(self):
        self.assertAlmostEqual(triangle_area(1, 1, 1), 0.43, places=2)

    def test_scalene_triangle_2_3_4(self):
        self.assertAlmostEqual(triangle_area(2, 3, 4), 2.90, places=2)

    def test_isosceles_triangle_5_5_6(self):
        s = 8.0
        area = (s * (s - 5) * (s - 5) * (s - 6)) ** 0.5
        self.assertAlmostEqual(triangle_area(5, 5, 6), round(area, 2), places=2)

    def test_triangle_7_10_12(self):
        self.assertAlmostEqual(triangle_area(7, 10, 12), 34.98, places=2)

    def test_triangle_float_sides(self):
        s = (2.5 + 3.5 + 4.0) / 2
        area = (s * (s - 2.5) * (s - 3.5) * (s - 4.0)) ** 0.5
        self.assertAlmostEqual(triangle_area(2.5, 3.5, 4.0), round(area, 2), places=2)

    def test_very_small_triangle(self):
        s = (0.1 + 0.1 + 0.1) / 2
        area = (s * (s - 0.1) * (s - 0.1) * (s - 0.1)) ** 0.5
        self.assertAlmostEqual(triangle_area(0.1, 0.1, 0.1), round(area, 2), places=2)

    def test_very_large_triangle(self):
        s = (1000 + 1000 + 1000) / 2
        area = (s * (s - 1000) * (s - 1000) * (s - 1000)) ** 0.5
        self.assertAlmostEqual(triangle_area(1000, 1000, 1000), round(area, 2), places=2)

    def test_invalid_sum_less_than_third_side(self):
        self.assertEqual(triangle_area(1, 2, 10), -1)

    def test_invalid_sum_equals_third_side(self):
        self.assertEqual(triangle_area(1, 1, 2), -1)

    def test_invalid_sum_equals_third_side_2(self):
        self.assertEqual(triangle_area(2, 3, 5), -1)

    def test_invalid_zero_side(self):
        self.assertEqual(triangle_area(0, 1, 1), -1)

    def test_invalid_all_zero(self):
        self.assertEqual(triangle_area(0, 0, 0), -1)

    def test_invalid_negative_side(self):
        self.assertEqual(triangle_area(-1, 5, 5), -1)

    def test_invalid_two_negative_sides(self):
        self.assertEqual(triangle_area(-1, -1, 5), -1)

    def test_invalid_one_negative_other_valid(self):
        self.assertEqual(triangle_area(1, -1, 1), -1)

    def test_none_as_first_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 4, 5)

    def test_none_as_second_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(3, None, 5)

    def test_none_as_third_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(3, 4, None)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            triangle_area("3", 4, 5)

    def test_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            triangle_area([3], 4, 5)

    def test_tuple_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            triangle_area((3,), 4, 5)

    def test_boolean_input(self):
        result = triangle_area(True, 1, 1)
        self.assertIn(result, [-1, 0.43])

    def test_integer_zero_and_valid_other_sides(self):
        self.assertEqual(triangle_area(0, 5, 5), -1)

    def test_perfect_square_area(self):
        self.assertEqual(triangle_area(5, 12, 13), 30.0)

    def test_area_rounding_up(self):
        s = (3 + 3 + 4) / 2
        area = (s * (s - 3) * (s - 3) * (s - 4)) ** 0.5
        self.assertAlmostEqual(triangle_area(3, 3, 4), round(area, 2), places=2)

    def test_degenerate_triangle_sum_equals(self):
        self.assertEqual(triangle_area(10, 10, 20), -1)

    def test_float_near_boundary_invalid(self):
        self.assertEqual(triangle_area(1.0, 1.0, 2.0), -1)

    def test_float_valid_triangle(self):
        s = (1.1 + 1.1 + 1.1) / 2
        area = (s * (s - 1.1) * (s - 1.1) * (s - 1.1)) ** 0.5
        self.assertAlmostEqual(triangle_area(1.1, 1.1, 1.1), round(area, 2), places=2)


import unittest

if __name__ == '__main__':
    unittest.main()
